(function(){
  'use strict';
  const KEY='safariPocketbookLanguageNotes';
  const prompts=['Hello','Thank you','Please','Where is…?','I need help','Please call emergency services'];
  const safe=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch(error){return{}}}
  function countryKey(country){return country.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')}
  window.countryLanguageHtml=function(country,languages){const notes=read()[countryKey(country)]||{},items=Object.values(languages||{}),chips=items.length?items.map(language=>`<span>${safe(language)}</span>`).join(''):'<span>Language reference unavailable offline</span>';return `<section class="entry-section language-section" data-language-country="${safe(country)}"><div class="entry-kicker">LANGUAGES &amp; LOCAL ETIQUETTE</div><h3>Communicate with care</h3><div class="country-languages">${chips}</div><p class="language-source">Country-language reference: bundled mledoze/countries snapshot dated 9 Sep 2026. Language prevalence, regional use and preferred greetings vary; confirm locally.</p><div class="phrase-notebook"><strong>Your locally verified phrase notes</strong><p>Add translations confirmed by a guide, host or fluent speaker. They remain on this device.</p>${prompts.map((prompt,index)=>`<label><span>${safe(prompt)}</span><input data-phrase-index="${index}" value="${safe(notes[index]||'')}" placeholder="Add a locally verified translation"><button type="button" data-speak-phrase="${index}" aria-label="Pronounce saved translation for ${safe(prompt)}">▶</button></label>`).join('')}<button type="button" class="save-phrases">Save phrase notes</button><small class="voice-disclosure">Pronunciation uses an available device-generated voice. It is not represented as a native-speaker recording.</small></div></section>`};
  window.mountCountryLanguage=function(country){const section=document.querySelector(`[data-language-country="${CSS.escape(country)}"]`);if(!section)return;const key=countryKey(country);section.querySelector('.save-phrases').addEventListener('click',()=>{const all=read();all[key]={};section.querySelectorAll('[data-phrase-index]').forEach(input=>{if(input.value.trim())all[key][input.dataset.phraseIndex]=input.value.trim()});localStorage.setItem(KEY,JSON.stringify(all));const toast=document.getElementById('toast');toast.textContent=`${country} phrase notes saved on this device.`;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)});section.addEventListener('click',event=>{const button=event.target.closest('[data-speak-phrase]');if(!button)return;const value=section.querySelector(`[data-phrase-index="${button.dataset.speakPhrase}"]`).value.trim();if(!value)return;window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(value))})};
})();
